const promptId = $json.prompt_id;

if (!promptId) {
  throw new Error('ComfyUI did not return prompt_id. Response: ' + JSON.stringify($json));
}

const source = $('Build ComfyUI Payload').first().json;

return [{
  json: {
    prompt_id: promptId,
    run_id: source.run_id,
    title: source.title,
    lyrics: source.lyrics,
    image_prompt: source.image_prompt,
    seed: source.seed
  }
}];

const state = $('Store Prompt ID').first().json;
const promptId = state.prompt_id;
const history = $json[promptId];

let done = false;
let failed = false;
let image = null;
let status = null;

if (history) {
  status = history.status || {};
  const statusText = JSON.stringify(status).toLowerCase();

  failed = statusText.includes('error') ||
           statusText.includes('exception') ||
           statusText.includes('execution_error');

  const node29 = history.outputs?.['29'];

  if (node29?.images?.length) {
    image = node29.images[0];
  }

  done = status.completed === true || !!image;
}

return [{
  json: {
    prompt_id: promptId,
    run_id: state.run_id,
    title: state.title,
    lyrics: state.lyrics,
    image_prompt: state.image_prompt,
    seed: state.seed,
    done,
    failed,
    image,
    status
  }
}];

const state = $('Check Done').first().json;

if (state.failed) {
  throw new Error(
    `ComfyUI execution failed. prompt_id=${state.prompt_id}\n` +
    JSON.stringify(state.status, null, 2)
  );
}

if (!state.image) {
  throw new Error(`ComfyUI reports done but node 29 has no image. prompt_id=${state.prompt_id}`);
